import type { Application as ClientApplication, Entity as ClientEntity } from '../client/types.ts';

import type { E2eAddedApplicationProperties } from './application.ts';

export type { Config, Features, Options, Source } from '../client/types.ts';

/** The other entity of a relationship. */
type E2eOtherEntity = NonNullable<ClientEntity['requiredRelationships']>[number]['otherEntity'];

/** The properties of an entity the e2e test frameworks share. */
export type E2eAddedEntityProperties = {
  /** An instance of the entity for the e2e tests, with its required fields not generated by the database. */
  e2eTestEntitySample?: Record<string, any>;
  /** An instance of the entity for the e2e tests, with its fields not generated by the database. */
  e2eTestEntity?: Record<string, any>;
  /** A sample of the entity for the e2e tests, missing when a required field gets no value. */
  e2eFakeData?: Record<string, any>;
  /** A sample value of each field for the e2e tests, the ones of e2eFakeData when it has them. */
  e2eFieldsFakeData?: Record<string, any>;
  /** The other entities of the required relationships, created before the entity by the e2e tests. */
  e2eRequiredOtherEntities?: E2eOtherEntity[];
  /** The other entities of the relationships, one by entity, whose lists the e2e tests intercept. */
  e2eOtherEntities?: E2eOtherEntity[];
  /** The e2e tests cannot create the entity: its required relationships or its data are out of their reach. */
  e2eSkipCreateTest?: boolean;
  /** The fields the create test of the e2e tests fills. */
  e2eCreateTestFields?: ClientEntity['fields'];
};

export type Entity = ClientEntity & E2eAddedEntityProperties;

export type Application<E extends Entity = Entity> = ClientApplication<E> & E2eAddedApplicationProperties;
